import{_ as r}from"./chunks/verwaltung-einstellungen-individual-einstellungen-farbe-statistik.PbWTgDXx.js";import{_ as l,o as a,c as t,a3 as i,j as e,a as s}from"./chunks/framework.z_KJ15Ep.js";const d="/bilder/probleme/tipp-wiedervorlage.png",h="/bilder/probleme/tipp-wiedervorlage-einstellungen.png",u="/bilder/probleme/tipp-schueler-eingabe-abbrechen.png",c="/bilder/probleme/alle-auswahl-klick.png",o="/bilder/probleme/alle-auswahl-ergebnis.png",g="/bilder/probleme/tipp-schnellzugriff-aktivieren.png",p="/bilder/probleme/tipp-schnellzugriff-setzen.png",b="/bilder/probleme/tipp-schnellzugriff-nutzen.png",m="/bilder/probleme/tipp-stammblatt-setzen.png",f="/bilder/probleme/tipp-stammblatt-drucken.png",W=JSON.parse('{"title":"SchILD-NRW im Alltag bedienen","description":"","frontmatter":{"title":"SchILD-NRW im Alltag bedienen","source_pageid":1257,"source_revision":6101},"headers":[],"relativePath":"hilfe/probleme/tipps-zur-bedienung-einfuehrung-in-schild-nrw.md","filePath":"hilfe/probleme/tipps-zur-bedienung-einfuehrung-in-schild-nrw.md"}'),S={name:"hilfe/probleme/tipps-zur-bedienung-einfuehrung-in-schild-nrw.md"};function z(k,n,v,w,_,E){return a(),t("div",null,[...n[0]||(n[0]=[i('<h1 id="schild-nrw-im-alltag-bedienen" tabindex="-1">SchILD-NRW im Alltag bedienen <a class="header-anchor" href="#schild-nrw-im-alltag-bedienen" aria-label="Permalink to &quot;SchILD-NRW im Alltag bedienen&quot;">​</a></h1><p>Passen Sie die Oberfläche an und nutzen Sie Tastaturbedienung, Wiedervorlage und Report-Schnellzugriffe für wiederkehrende Aufgaben.</p><p>In diesem Artikel finden sich Tipps zu den Bedienelementen von SchILD-NRW.</p><h2 id="nutzeroberflache" tabindex="-1">Nutzeroberfläche <a class="header-anchor" href="#nutzeroberflache" aria-label="Permalink to &quot;Nutzeroberfläche&quot;">​</a></h2><h3 id="spaltenbreiten-anpassen" tabindex="-1">Spaltenbreiten anpassen <a class="header-anchor" href="#spaltenbreiten-anpassen" aria-label="Permalink to &quot;Spaltenbreiten anpassen&quot;">​</a></h3><p>SchILD-NRW speichert die von Ihnen eingestellten Spaltenbreiten auf individueller Nutzerebene ab.</p><h3 id="statistikrelevante-felder-hervorheben" tabindex="-1">Statistikrelevante Felder hervorheben <a class="header-anchor" href="#statistikrelevante-felder-hervorheben" aria-label="Permalink to &quot;Statistikrelevante Felder hervorheben&quot;">​</a></h3><p><a href="/bilder/benutzer-einstellungen/verwaltung-einstellungen-individual-einstellungen-farbe-statistik.png"><img src="'+r+'" alt="Vergeben Sie eine Farbe, um statistikrelevante Felder hervorzugeben. Zur Oberfläche Luna wurde hier im Beispiel das Dunkelblau gewählt." loading="lazy"></a></p><p><em>Vergeben Sie eine Farbe, um statistikrelevante Felder hervorzugeben. Zur Oberfläche Luna wurde hier im Beispiel das Dunkelblau gewählt.</em></p><p>Heben sie für die Statistik relevante Felder farblich hervor, indem Sie Über <em>Verwaltung ➜ Individuelle Einstellungen ➜ Benutzeroberfläche</em> ➜ <strong>Farbe für statistikrelevante Felder</strong> eine passende Farbe setzen.</p><h2 id="listen-mit-checkboxen" tabindex="-1">Listen mit Checkboxen <a class="header-anchor" href="#listen-mit-checkboxen" aria-label="Permalink to &quot;Listen mit Checkboxen&quot;">​</a></h2><ul><li>Geben Sie einen Buchstaben ein. Die Liste öffnet sich und springt zum ersten passenden Eintrag.</li><li>Mit <code>Esc</code> schließen Sie die Liste wieder.</li><li>Drücken Sie bei geöffneter Liste die <code>Enter</code>-Taste, um das Häkchen des ausgewählten Eintrags zu setzen oder zu entfernen.</li><li>Navigieren Sie mit den <strong>Pfeiltasten</strong> in der Liste.</li><li>Über die <code>Entf</code>-Taste können alle Häkchen zurückgesetzt werden.</li></ul><h2 id="nutzen-sie-die-wiedervorlage" tabindex="-1">Nutzen Sie die <em>Wiedervorlage</em> <a class="header-anchor" href="#nutzen-sie-die-wiedervorlage" aria-label="Permalink to &quot;Nutzen Sie die *Wiedervorlage*&quot;">​</a></h2><p><a href="/bilder/probleme/tipp-wiedervorlage.png"><img src="'+d+'" alt="Legen Sie einen Eintrag in der Wiedervorlage an." loading="lazy"></a></p><p><em>Legen Sie einen Eintrag in der Wiedervorlage an.</em></p><p>Nutzen Sie die <em>Wiedervorlage</em> auf <em>Schüler ➜ Individualdaten I</em>, um sich einen Schüler nach Ablauf eines Datums mit einem Memo anzeigen zu lassen.</p><p>Das <strong>Weckersymbol</strong> öffnet die Wiedervorlage.</p><p><a href="/bilder/probleme/tipp-wiedervorlage-einstellungen.png"><img src="'+h+'" alt="Aktivieren Sie die Wiedervorlage in den Einstellungen." loading="lazy"></a></p><p><em>Aktivieren Sie die Wiedervorlage in den Einstellungen.</em></p><p>Wurde der Haken bei <em>Verwaltung ➜ Einstellungen ➜ Wiedervorlage</em> ➜ <strong>Wiedervorlage bei Programmstart prüfen</strong> gesetzt, geschieht genau dies und Wiedervorlagen mit verstrichenem Datum werden angezeigt.</p><p>Stellen Sie auch die Verfallszeiten für Wiedervorlagen ein.</p>',21),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),s("Tipp")]),e("p",null,"Denken Sie daran, dass Wiedervorlagen über Schulferien verfallen können.")],-1),i('<h2 id="fehlerhafte-eingabe-abbrechen" tabindex="-1">Fehlerhafte Eingabe abbrechen <a class="header-anchor" href="#fehlerhafte-eingabe-abbrechen" aria-label="Permalink to &quot;Fehlerhafte Eingabe abbrechen&quot;">​</a></h2><p><a href="/bilder/probleme/tipp-schueler-eingabe-abbrechen.png"><img src="'+u+'" alt="Wir überschreiben unabsichtlich einen Eintrag. Die Eingabe lässt sich Abbrechen, so lange das Feld noch nicht verlassen wurde." loading="lazy"></a></p><p><em>Wir überschreiben unabsichtlich einen Eintrag. Die Eingabe lässt sich <strong>Abbrechen</strong>, so lange das Feld noch nicht verlassen wurde.</em></p><p>Bemerken Sie auf dem Reiter <strong>Schüler</strong> während der Eingabe eine fehlerhafte oder versehentliche Eingabe, lassen Sie den Curser im Datenfeld stehen und klicken Sie oben auf <code>Abbrechen</code>.</p><p>Es wird der bisherige Inhalt des Feldes aus der Datenbank wiederhergestellt.</p><p>Bewegen Sie den Curser jedoch aus dem Feld heraus, wird das Feld in die Datenbank geschrieben, ohne dass es eine Funktion zum Rückgängig machen gibt.</p><h2 id="alle-schuler-auswahlen" tabindex="-1">Alle Schüler auswählen <a class="header-anchor" href="#alle-schuler-auswahlen" aria-label="Permalink to &quot;Alle Schüler auswählen&quot;">​</a></h2><p><a href="/bilder/probleme/alle-auswahl-klick.png"><img src="'+c+'" alt="Der Klick auf das Quadrat wählt &quot;alle Schüler&quot; aus." loading="lazy"></a></p><p><em>Der Klick auf das Quadrat wählt &quot;alle Schüler&quot; aus.</em></p><p>Um im Schülercontainer <em>alle Schüler</em> auszuwählen, klicken Sie auf das <em>Quadrat direkt über den Auswahlboxen</em>:</p><p><a href="/bilder/probleme/alle-auswahl-ergebnis.png"><img src="'+o+'" alt="Das Ergebnis: es sind alle SuS ausgewählt." loading="lazy"></a></p><p><em>Das Ergebnis: es sind alle SuS ausgewählt.</em></p><p>Nun sind alle Schüler im Schülercontainer ausgewählt worden.</p><h2 id="reports-schnellzugriff-und-schulbescheinigungen-stammblatt" tabindex="-1">Reports: Schnellzugriff und Schulbescheinigungen, Stammblatt <a class="header-anchor" href="#reports-schnellzugriff-und-schulbescheinigungen-stammblatt" aria-label="Permalink to &quot;Reports: Schnellzugriff und Schulbescheinigungen, Stammblatt&quot;">​</a></h2><h3 id="schnellzugriff-nutzen" tabindex="-1">Schnellzugriff nutzen <a class="header-anchor" href="#schnellzugriff-nutzen" aria-label="Permalink to &quot;Schnellzugriff nutzen&quot;">​</a></h3><p><a href="/bilder/probleme/tipp-schnellzugriff-aktivieren.png"><img src="'+g+'" alt="Aktiveren Sie den Schnellzugriff in Verwaltung ➜ Einstellungen." loading="lazy"></a></p><p><em>Aktiveren Sie den Schnellzugriff in Verwaltung ➜ Einstellungen.</em></p><p>Damit der Schnellzugriff zur Verfügung steht, muss dieser durch den Haken bei <strong>Schnellzugriff ermöglichen</strong> in <em>Verwaltung ➜ Einstellungen</em> in SchILD-NRW global aktiviert werden.</p><p><a href="/bilder/probleme/tipp-schnellzugriff-setzen.png"><img src="'+p+'" alt="Wählen Sie die Reports über in Verwaltung ➜ Einstellungen ➜ Individuelle Einstellungen ➜ Report-Schnellzugriff." loading="lazy"></a></p><p><em>Wählen Sie die Reports über in Verwaltung ➜ Einstellungen ➜ Individuelle Einstellungen ➜ Report-Schnellzugriff.</em></p><p>Wählen Sie über <em>Verwaltung ➜ Einstellungen ➜ Individuelle Einstellungen ➜ Report-Schnellzugriff</em> die Reports, die bei Ihrem Nutzer im Schnellzugriff auftauchen sollen.</p><p>Vergeben Sie auch eine Beschriftung für diesen Report.</p><p><a href="/bilder/probleme/tipp-schnellzugriff-nutzen.png"><img src="'+b+'" alt="Das schwebende Fenster des Schnellzugriffs." loading="lazy"></a></p><p><em>Das schwebende Fenster des Schnellzugriffs.</em></p><p>Nach einem Neustart steht nun das frei bewegbare schwebende Fenster des Schnellzugriffs mit den gesetzten Reports zur Verfügung.</p><h3 id="schulbescheinigungen-und-stammblatt" tabindex="-1">Schulbescheinigungen und Stammblatt <a class="header-anchor" href="#schulbescheinigungen-und-stammblatt" aria-label="Permalink to &quot;Schulbescheinigungen und Stammblatt&quot;">​</a></h3><p><a href="/bilder/probleme/tipp-stammblatt-setzen.png"><img src="'+m+'" alt="Setzen Sie ein Stammblatt und eine Schulbescheinigung zum schnellen Druck." loading="lazy"></a></p><p><em>Setzen Sie ein Stammblatt und eine Schulbescheinigung zum schnellen Druck.</em></p><p>Um das verwendete <em>Stammblatt</em> und die <em>Schulbescheinigung</em> schnell zu erreichen, klicken Sie mit der <code>Rechten Maustaste</code> auf den jeweils gewünschten Report und wählen Sie den Eintrag <code>Standard-Bescheinigung</code> oder <code>Standard-Stammblatt</code>.</p><p>Der Report ist nun entsprechend hinterlegt.</p><p><a href="/bilder/probleme/tipp-stammblatt-drucken.png"><img src="'+f+'" alt="Aufruf der gesetzten Reports im Reiter Schüler." loading="lazy"></a></p><p><em>Aufruf der gesetzten Reports im Reiter <strong>Schüler</strong>.</em></p><p>Im Reiter <strong>Schüler</strong> lassen sich die Reports nun im Kopfband im Bereich <em>Drucken</em> über einen Klick auf <code>Schulbescheinigung</code> oder <code>Stammblatt</code> direkt aufrufen.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Tipps_zur_Bedienung_(Einf%C3%BChrung_in_SchILD-NRW))" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6101.</p>',35)])])}const q=l(S,[["render",z]]);export{W as __pageData,q as default};
